paragraph.math:
$$\begin{array}{l}
  {\iiint\limits_{E}{\sqrt{x^{2} + z^{2}}\mathit{dV}} = {\iint\limits_{D_{3}}{{({4 - x^{2} - z^{2}})}\sqrt{x^{2} + z^{2}}\mathit{dA}}}} \\
  {\phantom{\iiint\limits_{E}{\sqrt{x^{2} + z^{2}}\mathit{dV}}} = {{\int_{0}^{2\pi}{\int_{0}^{2}{{({4 - r^{2}})}rr\mathit{dr}d\theta =}}}{\int_{0}^{2\pi}{d\theta}}{\int_{0}^{2}{{({4r^{2} - r^{4}})}\mathit{dr}}}}} \\
  {\phantom{\iiint\limits_{E}{\sqrt{x^{2} + z^{2}}\mathit{dV}}} = {2\pi\left\lbrack {\frac{4r^{3}}{3} - \frac{r^{5}}{5}} \right\rbrack_{0}^{2} = \frac{128\pi}{15}}}
  \end{array}$$

$$\begin{array}{l}
  {{\int_{0}^{1}{\int_{\sqrt{x}}^{1}{\int_{0}^{1 - y}{f\left( {x,y,z} \right)\mathit{dz}\mathit{dy}\mathit{dx}}}}} = {\int_{0}^{1}{\int_{0}^{y^{2}}{\int_{0}^{1 - y}{f\left( {x,y,z} \right)\mathit{dz}\mathit{dx}\mathit{dy}}}}}} \\
  {= {\int_{0}^{1}{\int_{0}^{1 - z}{\int_{0}^{y^{2}}{f\left( {x,y,z} \right)\mathit{dx}\mathit{dy}\mathit{dz}}}}} = {\int_{0}^{1}{\int_{0}^{1 - y}{\int_{0}^{y^{2}}{f\left( {x,y,z} \right)\mathit{dx}\mathit{dz}\mathit{dy}}}}}} \\
  {= {\int_{0}^{1}{\int_{0}^{1 - \sqrt{x}}{\int_{\sqrt{x}}^{1 - z}{f\left( {x,y,z} \right)\mathit{dy}\mathit{dz}\mathit{dx}}}}} = {\int_{0}^{1}{\int_{0}^{{(1 - z)}^{2}}{\int_{\sqrt{x}}^{1 - z}{f\left( {x,y,z} \right)\mathit{dy}\mathit{dx}\mathit{dz}}}}}}
  \end{array}$$
